const suppressEmailScoped = `-- name: SuppressEmailScoped :exec
INSERT INTO email_suppressions (workspace_id, email, reason, detail, scope, created_at)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (workspace_id, email) DO UPDATE SET reason = excluded.reason, detail = excluded.detail,
    scope = excluded.scope, created_at = excluded.created_at
WHERE email_suppressions.scope <> 'all' OR excluded.scope = 'all'
`

type SuppressEmailScopedParams struct {
	WorkspaceID uuid.UUID
	Email       string
	Reason      string
	Detail      string
	Scope       string
	Now         time.Time
}

// A complaint about a broadcast stops broadcasts only; it never narrows a suppression of all mail.
func (q *Queries) SuppressEmailScoped(ctx context.Context, arg SuppressEmailScopedParams) error {
	_, err := q.db.Exec(ctx, suppressEmailScoped,
		arg.WorkspaceID,
		arg.Email,
		arg.Reason,
		arg.Detail,
		arg.Scope,
		arg.Now,
	)
	return err
}
